-- Explicações por artigo — Lei do Racismo (Lei nº 7.716, de 1989). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão punidos, na forma desta Lei, os crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional.', '["Define o alcance da lei: raça, cor, etnia, religião ou procedência nacional.","Abrange discriminação e preconceito."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 9.459, de 15/05/97 (incluiu etnia, religião e procedência nacional).","Crime de racismo: inafiançável e imprescritível (Constituição, art. 5º, XLII)."]'::jsonb, 'Recusar atendimento a alguém por causa da cor da pele é crime previsto nesta lei.', '["Assertiva que limita a lei à discriminação de cor erra: abrange raça, cor, etnia, religião e procedência nacional."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'racismo' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Injúria racial: injuriar alguém, ofendendo-lhe a dignidade ou o decoro, em razão de raça, cor, etnia ou procedência nacional. Pena: reclusão de dois a cinco anos e multa. A pena é aumentada de metade se o crime for cometido mediante concurso de duas ou mais pessoas.', '["Ofensa à dignidade ou ao decoro por motivo de raça, cor, etnia ou procedência nacional.","Reclusão de dois a cinco anos e multa.","Aumento de metade se houver concurso de duas ou mais pessoas."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.532, de 2023; a injúria racial deixou o Código Penal e passou a ser crime de racismo.","Por ser racismo, é inafiançável e imprescritível.","O tipo não inclui religião."]'::jsonb, 'Chamar alguém de forma ofensiva por causa da cor da pele é injúria racial.', '["Assertiva que trata a injúria racial como crime prescritível e afiançável erra: é equiparada ao racismo."]'::jsonb, '[]'::jsonb, '["Injúria (Código Penal)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'racismo' and u.unit_key = 'art-2-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Impedir ou obstar o acesso de alguém, devidamente habilitado, a qualquer cargo da Administração Direta ou Indireta, bem como das concessionárias de serviços públicos. Pena: reclusão de dois a cinco anos. Incorre na mesma pena quem, por motivo de discriminação, obstar a promoção funcional.', '["Impedir acesso a cargo público ou de concessionária, estando a pessoa habilitada.","Reclusão de dois a cinco anos.","Mesma pena para quem obstar a promoção funcional por discriminação."]'::jsonb, '["ATUALIZAÇÃO: parágrafo único incluído pela Lei nº 12.288, de 2010 (Estatuto da Igualdade Racial).","A vítima precisa estar devidamente habilitada."]'::jsonb, 'Comissão impede candidato aprovado de assumir o cargo por causa da cor.', '["Assertiva que dispensa a habilitação da vítima erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'racismo' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Negar ou obstar emprego em empresa privada. Pena: reclusão de dois a cinco anos. Incorre na mesma pena quem, por discriminação, deixar de conceder equipamentos em igualdade de condições, impedir a ascensão funcional ou dar tratamento diferenciado no ambiente de trabalho, especialmente quanto ao salário. Quem exigir, em anúncios de emprego, aspectos de aparência próprios de raça ou etnia que a atividade não justifique fica sujeito a multa e prestação de serviços à comunidade.', '["Negar emprego em empresa privada: reclusão de dois a cinco anos.","§1º: equipamentos, ascensão funcional e tratamento diferenciado.","§2º: exigência de aparência racial em anúncios, com multa e prestação de serviços à comunidade."]'::jsonb, '["ATUALIZAÇÃO: parágrafos incluídos pela Lei nº 12.288, de 2010.","O §2º tem multa e prestação de serviços, não reclusão."]'::jsonb, 'Empresa recusa contratar candidato por causa da cor da pele.', '["Assertiva que aplica reclusão ao §2º erra: são multa e prestação de serviços."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'racismo' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

