select u.id, u.content_sha256, 'Os crimes previstos nesta Lei terão as penas aumentadas de um terço até a metade quando ocorrerem em contexto ou com intuito de descontração, diversão ou recreação.', '["Aumento de um terço até a metade.","Contexto ou intuito de descontração, diversão ou recreação."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.532, de 2023.","Afasta a tese de brincadeira."]'::jsonb, 'Racismo disfarçado de piada tem a pena aumentada.', '["Assertiva que trata a brincadeira como excludente de crime erra: ela aumenta a pena."]'::jsonb, '[]'::jsonb, '["Art. 20-B"]'::jsonb, 'under_review', 'claude'
